attributes.onChange:
{async (e) => {
            setRows([]);
            setErrors([]);
            setMessage("");
            const f = e.target.files?.[0];
            if (!f) return;
            if (f.size > 2_000_000) {
              setErrors(["Arquivo excede 2 MB."]);
              return;
            }
            try {
              const p = parseLeadCsv(await f.text());
              setRows(p.rows);
              setErrors(p.errors);
            } catch {
              setErrors(["Não foi possível ler o arquivo."]);
            }
          }}

attributes.onClick:
{() =>
              start(async () => {
                try {
                  const result = await importLeads(
                    rows.map((r) => ({
                      ...r,
                      ...(admin ? { sdr_id: owner } : {}),
                    })),
                  );
                  if (result.error) setErrors([result.error]);
                  else {
                    setRows([]);
                    setMessage(`${result.count} leads importados.`);
                    router.refresh();
                  }
                } catch {
                  setErrors([
                    "Não foi possível importar. Verifique a conexão; a prévia foi preservada.",
                  ]);
                }
              })
            }

{() =>
          start(async () => {
            if (!file) return;
            if (
              file.size < 1 ||
              file.size > 10485760 ||
              !allowedMime.includes(file.type as (typeof allowedMime)[number])
            ) {
              setError("Tipo não permitido ou arquivo maior que 10 MB.");
              return;
            }
            try {
              const record = await reserveFile({
                company_id: companyId,
                service_id: serviceId,
                contract_id: contractId,
                name: file.name,
                mime: file.type,
                size: file.size,
              });
              if (record.error || !record.path || !record.id) {
                setError(record.error ?? "Não foi possível iniciar o envio.");
                return;
              }
              const db = createBrowserClient(
                process.env.NEXT_PUBLIC_SUPABASE_URL!,
                process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
              );
              const upload = await db.storage
                .from(record.bucket!)
                .upload(record.path, file, {
                  contentType: file.type,
                  upsert: false,
                });
              if (upload.error) {
                setError(
                  "Upload não concluído. Verifique a conexão e tente novamente.",
                );
                return;
              }
              const r = await finishFile(record.id);
              if (r.error) setError(r.error);
              else {
                setMessage("Documento enviado com acesso privado.");
                setFile(null);
                if (inputRef.current) inputRef.current.value = "";
                router.refresh();
              }
            } catch {
              setError("Não foi possível enviar o arquivo. Tente novamente.");
            }
          })
        }

